#!/bin/sh
# Regenerates tests/air2spv-discard-atomic-spv.h (SPIR-V of discard_atomic.frag in the three discard flavours) for tests/air2spv-discard-robust-lavapipe.c. Needs glslangValidator and python3.
set -eu
cd "$(dirname "$0")"
OUT=../air2spv-discard-atomic-spv.h
{
  echo "/* GENERATED by tests/fixtures/gen-discard-atomic-spv.sh from discard_atomic.frag (glslangValidator; KILL with --target-env vulkan1.2 so that discard stays OpKill). SPDX-License-Identifier: MIT */"
  for m in KILL TERM DEMOTE; do
    env=vulkan1.3; [ "$m" = KILL ] && env=vulkan1.2   # vulkan1.3 turns `discard` into OpTerminateInvocation; vulkan1.2 (SPIR-V 1.5) keeps OpKill
    glslangValidator -V --target-env $env -D"MODE_$m" discard_atomic.frag -o /tmp/discard_atomic_$m.spv >/dev/null
    python3 - "$m" /tmp/discard_atomic_$m.spv <<'PY'
import sys, struct
d = open(sys.argv[2], 'rb').read()
w = struct.unpack('<%dI' % (len(d) // 4), d)
print('static const uint32_t DISCARD_ATOMIC_%s_SPV[] = {' % sys.argv[1])
for i in range(0, len(w), 8): print(','.join('0x%08x' % x for x in w[i:i+8]) + ',')
print('};')
PY
  done
} > "$OUT"
